struct SystemParams {
    double dx = 1.0;
};

// System RHS Evaluator: dy/dt = f(t, y)
inline void compute_derivatives(
    double t,
    const std::vector<double>& y,
    std::vector<double>& dy,
    const SystemParams& params
) {
    dy[0] = y[1];
    dy[1] = ((-1.0000000000000000e0) * y[0]);
}


namespace pratyaksh {

struct StepResult {
    double denominator;
    bool is_throttled;
};

// Generalized Unified Pratyaksh-II Integrator
template <typename SystemFunc, typename Params>
inline StepResult step_pratyaksh_ii(
    double t, double dt, std::vector<double>& y,
    std::vector<double>& k1, std::vector<double>& k2,
    std::vector<double>& k3, std::vector<double>& k4,
    std::vector<double>& temp, const SystemFunc& f,
    const Params& params,
    double alpha = 1.0, double beta = 2.0, double throttle_threshold = 5.0
) {
    const size_t dim = y.size();
    const double half_dt = 0.5 * dt;

    // Stage 1
    f(t, y, k1, params);
    for (size_t i = 0; i < dim; ++i) temp[i] = y[i] + half_dt * k1[i];

    // Stage 2
    f(t + half_dt, temp, k2, params);
    for (size_t i = 0; i < dim; ++i) temp[i] = y[i] + half_dt * k2[i];

    // Stage 3
    f(t + half_dt, temp, k3, params);
    for (size_t i = 0; i < dim; ++i) temp[i] = y[i] + dt * k3[i];

    // Stage 4
    f(t + dt, temp, k4, params);

    // Compute Curvature Vector C = K4 - K3 - K2 + K1
    // and Scale Factor S_n = ||y_n|| + ||K1|| + eps
    double c_norm_sq = 0.0;
    double y_norm_sq = 0.0;
    double k1_norm_sq = 0.0;

    for (size_t i = 0; i < dim; ++i) {
        double K1 = dt * k1[i];
        double K2 = dt * k2[i];
        double K3 = dt * k3[i];
        double K4 = dt * k4[i];

        double c_i = K4 - K3 - K2 + K1;
        c_norm_sq += c_i * c_i;
        y_norm_sq += y[i] * y[i];
        k1_norm_sq += K1 * K1;
    }

    double c_norm = std::sqrt(c_norm_sq);
    double s_n = std::sqrt(y_norm_sq) + std::sqrt(k1_norm_sq) + 1e-12;

    // Dimensionless normalized curvature
    double c_hat = c_norm / s_n;

    // Unified Bounded Denominator: D = 6.0 + (alpha * c_hat)^beta
    double d_perturbation = std::pow(alpha * c_hat, beta);
    double denominator = 6.0 + d_perturbation;
    double inv_denominator = 1.0 / denominator;

    // State update with unified limiter
    for (size_t i = 0; i < dim; ++i) {
        double K1 = dt * k1[i];
        double K2 = dt * k2[i];
        double K3 = dt * k3[i];
        double K4 = dt * k4[i];
        double numerator = K1 + 2.0 * K2 + 2.0 * K3 + K4;
        y[i] += numerator * inv_denominator;
    }

    StepResult res;
    res.denominator = denominator / 6.0; // Normalized stiffness monitor (1.0 = unstiff)
    res.is_throttled = (res.denominator > throttle_threshold);
    return res;
}

// Classical RK4 (Baseline comparator)
template <typename SystemFunc, typename Params>
inline StepResult step_rk4(
    double t, double dt, std::vector<double>& y,
    std::vector<double>& k1, std::vector<double>& k2,
    std::vector<double>& k3, std::vector<double>& k4,
    std::vector<double>& temp, const SystemFunc& f,
    const Params& params
) {
    const size_t dim = y.size();
    const double half_dt = 0.5 * dt;

    f(t, y, k1, params);
    for (size_t i = 0; i < dim; ++i) temp[i] = y[i] + half_dt * k1[i];

    f(t + half_dt, temp, k2, params);
    for (size_t i = 0; i < dim; ++i) temp[i] = y[i] + half_dt * k2[i];

    f(t + half_dt, temp, k3, params);
    for (size_t i = 0; i < dim; ++i) temp[i] = y[i] + dt * k3[i];

    f(t + dt, temp, k4, params);

    for (size_t i = 0; i < dim; ++i) {
        double K1 = dt * k1[i];
        double K2 = dt * k2[i];
        double K3 = dt * k3[i];
        double K4 = dt * k4[i];
        y[i] += (K1 + 2.0 * K2 + 2.0 * K3 + K4) / 6.0;
    }

    StepResult res;
    res.denominator = 1.0;
    res.is_throttled = false;
    return res;
}

} // namespace pratyaksh


extern "C" {
    struct SimulationResultC {
        int status; // 0=SUCCESS, 1=DIVERGED, 2=ABORTED_UNPHYSICAL
        double final_time;
        size_t steps_taken;
        size_t throttled_steps;
        double max_denominator;
        double execution_time_sec;
    };

    void run_simulation_batch(
        size_t num_ics,
        const double* y0_batch, 
        size_t dim, 
        double t_start, double t_end, double dt, double beta, 
        int integrator_choice, // 0=pratyaksh_ii, 1=rk4
        double* final_y_batch, 
        SimulationResultC* results
    ) {
        SystemParams params;
        
        for (size_t b = 0; b < num_ics; ++b) {
            std::vector<double> y(dim);
            for(size_t d=0; d<dim; ++d) {
                y[d] = y0_batch[b * dim + d];
            }

            std::vector<double> k1(dim, 0.0);
            std::vector<double> k2(dim, 0.0);
            std::vector<double> k3(dim, 0.0);
            std::vector<double> k4(dim, 0.0);
            std::vector<double> temp(dim, 0.0);

            double t = t_start;
            size_t steps_taken = 0;
            size_t throttled_steps = 0;
            double max_denominator = 1.0;
            int status = 0; // SUCCESS

            auto start_time = std::chrono::high_resolution_clock::now();

            while (t < t_end - 1e-12) {
                double current_dt = dt;
                if (t + current_dt > t_end) current_dt = t_end - t;

                pratyaksh::StepResult res;
                if (integrator_choice == 0) {
                    res = pratyaksh::step_pratyaksh_ii(t, current_dt, y, k1, k2, k3, k4, temp, compute_derivatives, params, 1.0, beta);
                } else {
                    res = pratyaksh::step_rk4(t, current_dt, y, k1, k2, k3, k4, temp, compute_derivatives, params);
                }

                if (res.denominator > max_denominator) max_denominator = res.denominator;
                if (res.is_throttled) throttled_steps++;

                // Early-Stopping Guillotine
                if (res.denominator > 1e10) {
                    status = 2; // ABORTED_UNPHYSICAL
                    break;
                }

                bool diverged = false;
                for (size_t d = 0; d < dim; ++d) {
                    if (std::isnan(y[d]) || std::isinf(y[d])) {
                        diverged = true;
                        break;
                    }
                }
                
                if (diverged) {
                    status = 1; // DIVERGED
                    break;
                }

                t += current_dt;
                steps_taken++;
            }

            auto end_time = std::chrono::high_resolution_clock::now();
            double exec_time = std::chrono::duration<double>(end_time - start_time).count();

            // Save results
            results[b].status = status;
            results[b].final_time = t;
            results[b].steps_taken = steps_taken;
            results[b].throttled_steps = throttled_steps;
            results[b].max_denominator = max_denominator;
            results[b].execution_time_sec = exec_time;

            for(size_t d=0; d<dim; ++d) {
                final_y_batch[b * dim + d] = y[d];
            }
        }
    }
}
